'use strict';
// REGREV precision lab: seek >60% WR without using HOLD for selection. Research only.
const fs=require('fs'),R=JSON.parse(fs.readFileSync('data/xauusd-m5-dukascopy.json','utf8'));
const M=R.map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t),N=M.length,C=Math.floor(N*.75);
function ema(p){let E=[],e=M[0].c,k=2/(p+1);for(let i=0;i<N;i++){e=M[i].c*k+e*(1-k);E[i]=e}return E}function atr(p=14){let A=Array(N).fill(NaN);for(let i=p;i<N;i++){let s=0;for(let j=i-p+1;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));A[i]=s/p}return A}const A=atr(),E20=ema(20);function av(i,n=50){let s=0,c=0;for(let j=i-n;j<i;j++)if(Number.isFinite(A[j])){s+=A[j];c++}return c?s/c:NaN}const hour=i=>new Date(M[i].t).getUTCHours();
function raw(i,q){let aa=av(i);if(!(A[i]/aa>=q.ar))return;let b=M[i],p=M[i-1],rg=b.h-b.l;if(!(rg>0))return;let bull=b.c>b.o,bear=b.c<b.o,body=Math.abs(b.c-b.o)/rg,cpB=(b.c-b.l)/rg,cpS=(b.h-b.c)/rg;if(body<q.body||q.block.includes(hour(i)))return;let prevRange=(p.h-p.l)/A[i],move=Math.abs(b.c-p.c)/A[i];if(prevRange<q.prevRange||move<q.move)return;if(q.side!=='SELL'&&(E20[i]-b.c)/A[i]>=q.dist&&bull&&cpB>=q.cp)return'BUY';if(q.side!=='BUY'&&(b.c-E20[i])/A[i]>=q.dist&&bear&&cpS>=q.cp)return'SELL'}
function run(q,lo,hi){let T=[],o=null,pending=null;for(let i=Math.max(100,lo);i<Math.min(N-2,hi);i++){if(o){let b=M[i],px=null;if(o.s==='BUY'){if(b.l<=o.sl)px=o.sl;else if(b.h>=o.tp)px=o.tp}else{if(b.h>=o.sl)px=o.sl;else if(b.l<=o.tp)px=o.tp}if(px==null&&i-o.ei+1>=q.hold)px=b.c;if(px!=null){T.push({...o,r:o.s==='BUY'?(px-o.en)/(o.en-o.sl):(o.en-px)/(o.sl-o.en)});o=null}continue}if(pending){let b=M[i],rg=b.h-b.l,ok=rg>0&&(pending.s==='BUY'?b.c>b.o&&(b.c-b.l)/rg>=q.confirm:b.c<b.o&&(b.h-b.c)/rg>=q.confirm);if(ok){let en=M[i+1].o,r=q.sl*A[i];o={s:pending.s,en,sl:pending.s==='BUY'?en-r:en+r,tp:pending.s==='BUY'?en+q.rr*r:en-q.rr*r,ei:i+1};pending=null}else pending=null;continue}let s=raw(i,q);if(!s)continue;if(q.two)pending={s};else{let en=M[i+1].o,r=q.sl*A[i];o={s,en,sl:s==='BUY'?en-r:en+r,tp:s==='BUY'?en+q.rr*r:en-q.rr*r,ei:i+1}}}return T}function st(T){let w=0,g=0,l=0,e=0,p=0,dd=0,ls=0,ml=0;for(let x of T){e+=x.r;if(x.r>0){w++;g+=x.r;ls=0}else{l+=-x.r;ls++;ml=Math.max(ml,ls)}p=Math.max(p,e);dd=Math.max(dd,p-e)}return{n:T.length,wr:T.length?100*w/T.length:0,pf:l?g/l:g?99:0,net:e,dd,ls:ml}}
const blocks=[ [20,21,22,23],[0,20,21,22,23],[19,20,21,22,23],[6,7,8,20,21,22,23] ];let X=[];for(let side of ['BOTH','BUY','SELL'])for(let ar of [1.2,1.25,1.3,1.4,1.5])for(let dist of [2,2.1,2.2,2.3,2.4])for(let cp of [.65,.7,.75,.8])for(let body of [.2,.25,.35,.45])for(let prevRange of [0,.8,1.1])for(let move of [0,.15,.3])for(let two of [false,true])for(let confirm of (two?[.55,.65,.75]:[0]))for(let block of blocks){let q={side,ar,dist,cp,body,prevRange,move,two,confirm,block,sl:1,rr:1.5,hold:8},d=st(run(q,0,C));if(d.n<35)continue;let score=(d.wr>=60?35:0)+(d.wr-50)*1.5+Math.min(d.pf,3)*8+d.net*.35-d.dd;X.push({q,d,score})}X.sort((a,b)=>b.score-a.score);
console.log(`REGREV 60% PRECISION LAB | M5=${N} DEV=${C} HOLD=${N-C}`);console.log('HOLD IS NOT USED FOR RANKING | EXIT fixed SL1 / TP1.5R / HOLD8');console.log('\n🎯 TOP DEV CANDIDATES');X.slice(0,40).forEach((x,k)=>{let h=st(run(x.q,C,N));console.log(`${k+1} ${JSON.stringify(x.q)} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net>=0?'+':''}${x.d.net.toFixed(2)} DD${x.d.dd.toFixed(2)} | HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.net>=0?'+':''}${h.net.toFixed(2)} DD${h.dd.toFixed(2)}`)});
console.log('\n🔥 DEV >=60% WR, >=40 trades');X.filter(x=>x.d.wr>=60&&x.d.n>=40).slice(0,30).forEach((x,k)=>{let h=st(run(x.q,C,N));console.log(`${k+1} ${JSON.stringify(x.q)} | DEV ${x.d.n}/${x.d.wr.toFixed(1)}% PF${x.d.pf.toFixed(2)} | HOLD ${h.n}/${h.wr.toFixed(1)}% PF${h.pf.toFixed(2)} N${h.net.toFixed(2)}`)});
console.log('\n🏁 TRUE 60/60 SURVIVORS (diagnostic only; HOLD was never ranked)');let S=X.filter(x=>x.d.wr>=60&&x.d.n>=40).map(x=>({x,h:st(run(x.q,C,N))})).filter(z=>z.h.n>=15&&z.h.wr>=60&&z.h.pf>=1.3&&z.h.net>0);if(!S.length)console.log('NONE — current REGREV structure did not honestly sustain 60%+ on both DEV and HOLD.');else S.slice(0,20).forEach((z,k)=>console.log(`${k+1} ${JSON.stringify(z.x.q)} | DEV T${z.x.d.n} WR${z.x.d.wr.toFixed(1)} PF${z.x.d.pf.toFixed(2)} N${z.x.d.net.toFixed(2)} | HOLD T${z.h.n} WR${z.h.wr.toFixed(1)} PF${z.h.pf.toFixed(2)} N${z.h.net.toFixed(2)}`));